// Standalone source-only trace test; no original executable or assets needed.
// Expected traces were transcribed from the bounded Premium control/data-flow
// analysis at 0x009d4828 BEFORE running this candidate, not generated by it.
// F/A sample both records at allocator entry; R samples the returned record
// and final state. Addresses below are source-owned sentinels, never dereferenced.
#include "../../../recovered/libNOVA3_neon/driver_callback.h"

#include <climits>
#include <cstdlib>
#include <initializer_list>
#include <iostream>
#include <vector>

using Driver = vox::DriverCallbackInterface;
using Buffer = Driver::BufferRef;

// Production definitions remain owned by driver_callback_init.cpp. Only this
// standalone test supplies them, since its specified link omits that TU.
Buffer Driver::m_sWorkBuffer;
Buffer Driver::m_sMixingBuffer;

namespace {
char oldStorage, newStorage, mixingStorage;
void* const oldData = &oldStorage;
void* const newData = &newStorage;
void* const mixData = &mixingStorage;
void* allocationResult;

struct Event {
    char kind;
    unsigned bytes;
    void* pointer;
    int workSize;
    void* workData;
    int mixSize;
    void* mixingData;
};
std::vector<Event> events;

void record(char kind, unsigned bytes, void* pointer) {
    events.push_back({kind, bytes, pointer, Driver::m_sWorkBuffer.size,
                      Driver::m_sWorkBuffer.data, Driver::m_sMixingBuffer.size,
                      Driver::m_sMixingBuffer.data});
}

void reset(int size, void* data, void* result = newData) {
    Driver::m_sWorkBuffer = {size, data};
    Driver::m_sMixingBuffer = {777, mixData};
    allocationResult = result;
    events.clear();
}

void request(int bytes) {
    record('R', 0, Driver::GetWorkBuffer(bytes));
}

void expect(const char* name, std::initializer_list<Event> expected) {
    if (events.size() != expected.size()) {
        std::cerr << name << ": event count mismatch\n";
        std::exit(1);
    }
    unsigned i = 0;
    for (const auto& want : expected) {
        const auto& got = events[i];
        if (got.kind != want.kind || got.bytes != want.bytes ||
            got.pointer != want.pointer || got.workSize != want.workSize ||
            got.workData != want.workData || got.mixSize != want.mixSize ||
            got.mixingData != want.mixingData) {
            std::cerr << name << ": event " << i << " mismatch\n";
            std::exit(1);
        }
        ++i;
    }
    events.clear();
}
} // namespace

void VoxFree(void* pointer) { record('F', 0, pointer); }
void* VoxAlloc(unsigned bytes) {
    record('A', bytes, nullptr);
    return allocationResult;
}

int main() {
    static_assert(sizeof(int) == 4 && sizeof(unsigned) == 4,
                  "Reference count and allocation argument are 32-bit");
    reset(0, nullptr);
    request(0);
    request(-1);
    request(INT_MIN);
    expect("initial nonpositive requests", {
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
    });
    request(17);
    expect("initial allocation is unscaled", {
        {'A', 17, nullptr, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 17, newData, 777, mixData},
    });
    request(16);
    request(17);
    request(-1);
    expect("smaller equal negative reuse", {
        {'R', 0, &Driver::m_sWorkBuffer, 17, newData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 17, newData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 17, newData, 777, mixData},
    });

    reset(17, oldData);
    request(18);
    expect("growth retains old state through both calls", {
        {'F', 0, oldData, 17, oldData, 777, mixData},
        {'A', 18, nullptr, 17, oldData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 18, newData, 777, mixData},
    });

    reset(17, oldData, nullptr);
    request(18);
    expect("growth failure clears record after allocation", {
        {'F', 0, oldData, 17, oldData, 777, mixData},
        {'A', 18, nullptr, 17, oldData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
    });
    request(18);
    expect("failed request retries without free", {
        {'A', 18, nullptr, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
    });
    allocationResult = newData;
    request(18);
    expect("retry success", {
        {'A', 18, nullptr, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 18, newData, 777, mixData},
    });

    reset(0, nullptr, nullptr);
    request(1);
    expect("initial failure", {
        {'A', 1, nullptr, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 0, nullptr, 777, mixData},
    });
    reset(17, nullptr);
    request(17);
    expect("null alone does not trigger allocation", {
        {'R', 0, &Driver::m_sWorkBuffer, 17, nullptr, 777, mixData},
    });
    request(18);
    expect("growth with null skips free", {
        {'A', 18, nullptr, 17, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, 18, newData, 777, mixData},
    });

    // Artificial record states distinguish signed comparison from unsigned,
    // and check argument-bit preservation without any real huge allocation.
    reset(INT_MIN, oldData);
    request(-1);
    expect("signed growth and unsigned argument bits", {
        {'F', 0, oldData, INT_MIN, oldData, 777, mixData},
        {'A', 0xffffffffu, nullptr, INT_MIN, oldData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, -1, newData, 777, mixData},
    });
    reset(0, nullptr);
    request(INT_MAX);
    request(INT_MAX);
    expect("largest positive request no arithmetic overflow", {
        {'A', 0x7fffffffu, nullptr, 0, nullptr, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, INT_MAX, newData, 777, mixData},
        {'R', 0, &Driver::m_sWorkBuffer, INT_MAX, newData, 777, mixData},
    });
    std::cout << "driver_callback_work_buffer_test: passed\n";
}
